# orbit.moph — 太陽系。惑星が異なる半径・周期で公転し、月が地球を回る

import math

let total = 15s
let cx = 8
let cy = 4.5

let comp = Composition(box = Vector(16, 9), duration = total)
comp.place("bg", Rect(position = Vector(0, 0), anchor = Vector(0, 0), w = 16, h = 9, fill = #101020), in = 0s, out = total)

let planets = [
  { "r": 1.6, "size": 0.16, "period": 3s,  "color": #c0c0c0 },
  { "r": 2.5, "size": 0.26, "period": 5s,  "color": #e0a060 },
  { "r": 3.4, "size": 0.28, "period": 8s,  "color": #4080e0 },
  { "r": 4.2, "size": 0.20, "period": 12s, "color": #e05040 },
]

# 軌道の線 (fill なし、stroke だけの Circle)
let rings = []
for p in planets {
  rings.push(Circle(position = Vector(cx, cy), radius = p["r"], stroke = #303050, strokeWidth = 0.02))
}
comp.place("rings", Group(...rings), in = 0s, out = total)

# 太陽。脈動は 4 秒ごとにくり返す 3 つのキーフレーム
let pulse = progress [:radius] {
  0:   0.9
  0.5: 1.05 :ease
  1:   0.9  :ease
}

func sun(t) {
  Circle(position = Vector(cx, cy), radius = pulse((t / 4s) % 1)[0], fill = #f0c040)
}
comp.place("sun", sun, in = 0s, out = total)

# 円軌道。period で 1 周する速さを決める
func orbit_at(t, r, period) {
  let a = math.tau * (t / period)
  Vector(cx + r * math.cos(a), cy + r * math.sin(a))
}

func planet(r, size, period, color) {
  func (t) { Circle(position = orbit_at(t, r, period), radius = size, fill = color) }
}

for (i, p) in planets.enumerate() {
  comp.place("planet-{i}".format(i), planet(p["r"], p["size"], p["period"], p["color"]), in = 0s, out = total)
}

# 地球 (r = 3.4, 8 秒で 1 周) の月。地球の位置に、6 倍速の小さな円運動を足す
func moon(t) {
  let a = math.tau * (t / 8s)
  Circle(position = Vector(cx + 3.4 * math.cos(a) + 0.5 * math.cos(a * 6), cy + 3.4 * math.sin(a) + 0.5 * math.sin(a * 6)), radius = 0.08, fill = #d0d0d0)
}
comp.place("moon", moon, in = 0s, out = total)

func title(t) {
  TextArea(text = "orbit", position = Vector(0.4, 0.3), anchor = Vector(0, 0), fontSize = 0.6, fill = #e0e0f0, opacity = ease(t, 0s, 1.5s, 0, 1))
}
comp.place("title", title, in = 0s, out = total)

output comp

# fractal.moph — 枝分かれする木。各枝は親の先端から生え、親が動けば子も動く
# 部品が互いに依存する形: 枝は親の先端の位置を受け取って描く。木は根から順に伸び、伸び切ったら風に揺れる

import math

# ---------- 形と時間の決まり ----------
let levels     = 8            # 枝分かれの回数 (枝は 2^(levels+1) - 1 本)
let total      = 14s          # 動画の長さ
let trunk_len  = 2.1
let shrink     = 0.72         # 1 段ごとの長さの比
let spread     = 0.46         # 枝の開き (rad)
let grow_time  = 0.9          # 1 段が伸びる秒数
let grow_gap   = 0.5          # 次の段が伸び始めるまでの秒数
let sway_amp   = 0.035        # 揺れの角度 (rad)。先端ほど大きい
let sway_period = 4.5         # 揺れの周期 (秒)
let colors = [#7a4f33, #8a5c3a, #97693f, #8c7a42, #7c8c45, #62984c, #4aa25a, #46ad78, #6cc496]

let comp = Composition(box = Vector(16, 9), duration = total)
comp.place("bg", Rect(position = Vector(0, 0), anchor = Vector(0, 0), w = 16, h = 9, fill = #0d1117), in = 0s, out = total)

func smooth_bands(k) { k * k * (3 - 2 * k) }

# level 段目の枝が seconds 秒の時点でどこまで伸びているか (0..1)
func growth(seconds, level) {
  let k = (seconds - level * grow_gap) / grow_time
  smooth_bands(math.min(1, math.max(0, k)))
}

# 揺れ。段が深いほど大きく、phase で枝ごとにずらす
func sway(seconds, level, phase) {
  sway_amp * level * math.sin(seconds / sway_period * math.tau + phase)
}

func direction(angle) { Vector(math.cos(angle), -math.sin(angle)) }

# 親の先端 from から角度 angle に伸びる枝を items に足し、その先にさらに 2 本足す
func branch(items, seconds, from, angle, len, level, phase) {
  let tip = from + direction(angle + sway(seconds, level, phase)) * (len * growth(seconds, level))
  items.push(Line(from = from, to = tip, stroke = colors[level], strokeWidth = 0.18 * shrink ^ level, opacity = 0.95))
  if level < levels {
    branch(items, seconds, tip, angle + spread, len * shrink, level + 1, phase + 0.4)
    branch(items, seconds, tip, angle - spread, len * shrink, level + 1, phase - 0.4)
  } else {
    # 先端の葉。枝が伸び切ってから出る
    items.push(Circle(position = tip, radius = 0.06, fill = #b9e88a, opacity = growth(seconds, level + 1) * 0.9))
  }
}

# 幹は地面から。先端は伸びるだけで揺れない
let root = Vector(8, 8.6)

func tree(t) {
  let seconds = t / 1s
  let tip = root + direction(math.pi / 2) * (trunk_len * growth(seconds, 0))
  let items = [Line(from = root, to = tip, stroke = colors[0], strokeWidth = 0.18, opacity = 0.95)]
  branch(items, seconds, tip, math.pi / 2 + spread, trunk_len * shrink, 1, 0.4)
  branch(items, seconds, tip, math.pi / 2 - spread, trunk_len * shrink, 1, -0.4)
  Group(...items)
}
comp.place("tree", tree, in = 0s, out = total)

output comp

# walker.moph — 歩く人。関節ごとの図形が、親の先端から次の関節へつながる (腰 → 腿 → 脛 → 足、肩 → 上腕 → 前腕)。
# 歩行の周期は sin で作る。脚が前に振れるとき膝が曲がり、着いているときは伸びる。腕は同じ側の脚と逆に振る。
# make(near, far, t) が「その場で歩く人」の Group (箱 6 x 6、足元は y 5.6) を、時刻 t のぶんだけ返す。import して並べられる。
# 進むのは置いた側の仕事で、箱の幅 6 のとき 1 秒に speed 進めると足が滑らない

import math

# ---------- 体の寸法と歩き方 ----------
export let period = 1.2    # 1 周期 (左右 1 歩ずつ) の秒数
export let speed  = 3.1    # 歩幅に合う進む速さ (箱の単位 / 秒)
export let floor  = 5.6    # 箱の中の足元の高さ
let thigh   = 1.4
let shin    = 1.3
let torso   = 1.6
let upper   = 1.1
let fore    = 1.0
let swing   = 0.35         # 腿の振れ幅 (rad)
let width   = 0.13

# 角度 0 が真下、正が前 (x が増える向き)
func direction(a) { Vector(math.sin(a), math.cos(a)) }
# 歩行の位相。side は 0 (手前) か 1 (奥) で半周期ずれる
func phase(t, side) { math.tau * (t / 1s) / period + side * math.pi }
func hip_at(t) { Vector(3, floor - thigh - shin + 0.15 - 0.07 * math.cos(2 * phase(t, 0))) }
func thigh_angle(p) { swing * math.sin(p) }
# 前に振れている間 (cos > 0) だけ膝を曲げる
func shin_angle(p) { thigh_angle(p) - 0.1 - 0.9 * math.max(0, math.cos(p)) }
func upper_angle(p) { -0.6 * math.sin(p) }
func fore_angle(p) { upper_angle(p) + 0.55 }

func limb(from, to, color) { Line(from = from, to = to, stroke = color, strokeWidth = width) }
func joint(at, color, r) { Circle(position = at, radius = r, fill = color) }

# 片側の脚と腕。親の先端を次の起点にしてつなぐ。戻り値は図形の List
func side_of(side, color, t) {
  let p = phase(t, side)
  let hip = hip_at(t)
  let knee = hip + direction(thigh_angle(p)) * thigh
  let ankle = knee + direction(shin_angle(p)) * shin
  let toe = ankle + direction(shin_angle(p) + math.pi / 2) * 0.35
  let shoulder = hip + Vector(0.12, -torso)
  let elbow = shoulder + direction(upper_angle(p)) * upper
  let hand = elbow + direction(fore_angle(p)) * fore
  [
    limb(hip, knee, color), limb(knee, ankle, color), limb(ankle, toe, color),
    limb(shoulder, elbow, color), limb(elbow, hand, color),
    joint(knee, color, width / 2), joint(ankle, color, width / 2),
    joint(elbow, color, width / 2), joint(hand, color, width * 0.7),
  ]
}

# 胴と頭
func trunk_of(color, t) {
  let hip = hip_at(t)
  let neck = hip + Vector(0.12, -torso)
  [
    limb(hip, neck, color),
    joint(hip, color, width * 0.8), joint(neck, color, width / 2),
    joint(neck + Vector(0.08, -0.5), color, 0.36),
  ]
}

# その場で歩く人。near は手前の手足と胴の色、far は奥の手足の色、t は歩き始めからの時刻
export func make(near: Color, far: Color, t: Duration) -> Group {
  # 奥 → 胴 → 手前 の順に重ねる
  Group(...side_of(1, far, t), ...trunk_of(near, t), ...side_of(0, near, t))
}

# ---------- 単体で見るとき: 1 人が左から右へ横切る ----------
let total = 7s
let ground_y = 8

func one(t) {
  make(#e8ecf7, #8b93a7, t).copy(anchor = Vector(0, 6), position = Vector(-5 + speed * (t / 1s), ground_y + 6 - floor))
}

let comp = Composition(box = Vector(16, 9), duration = total)
comp.place("bg", Rect(position = Vector(0, 0), anchor = Vector(0, 0), w = 16, h = 9, fill = #14161c), in = 0s, out = total)
comp.place("ground", Line(from = Vector(0, ground_y), to = Vector(16, ground_y), stroke = #3a4560, strokeWidth = 0.04), in = 0s, out = total)
comp.place("person", one, in = 0s, out = total)

output comp

# crowd.moph — 夕暮れの通り。walker.moph の make() で作った人たちが、奥行きの違う位置を歩いていく。
# 奥の人ほど小さく、薄く、ゆっくり (幅に比例した速さなので足は滑らない)。空は Shader のグラデーション。
# 日が暮れると街灯が点き、遠くの窓に灯りが入り、星が出て、最後に全体が暗転する

import math
import { make, speed, floor } from .walker

let total = 26s
let seconds = total / 1s
let dusk_end = 4        # ここから暗くなり始める (秒)
let night_at = 18       # 完全に夜になる (秒)

let comp = Composition(box = Vector(16, 9), duration = total)

# 空: 上は群青、地平線は橙。dusk_end から night_at にかけて夜になる
let dusk = Shader(color = func (x, y, t) {
    let k = y / 6.2
    let night = math.min(1, math.max(0, (t - dusk_end) / (night_at - dusk_end)))
    let top = #1c2452 * (1 - night) + #05070f * night
    let horizon = #f0965a * (1 - night) + #2a2236 * night
    top * (1 - k * k) + horizon * (k * k)
  })
comp.place("sky", Rect(position = Vector(0, 0), anchor = Vector(0, 0), w = 16, h = 6.2, fill = dusk), in = 0s, out = total)

# 星: 夜になってから出て、瞬く
func stars(t) {
  let now = t / 1s
  Group(...(0..30).map(func (i) {
    let shown = math.min(1, math.max(0, (now - 15 - i * 0.1) / 3)) * (0.5 + 0.5 * math.sin(math.tau * now / 2 + i))
    Circle(position = Vector((math.sin(i * 12.9898) * 43758.5453) % 1 * 16, (math.sin(i * 78.233) * 43758.5453) % 1 * 3.5), radius = 0.03, fill = #ffffff, opacity = shown)
  }))
}
comp.place("stars", stars, in = 0s, out = total)
comp.place("ground", Rect(position = Vector(0, 6.2), anchor = Vector(0, 0), w = 16, h = 2.8, fill = #1a1d2a), in = 0s, out = total)

# 遠くの街並みと、その窓 (夜に順に点く)
let buildings = []
let windows = []
for i in 0..14 {
  let h = 0.4 + 0.9 * (0.5 + 0.5 * math.sin(i * 2.3))
  let x = i * 1.2 - 0.3
  buildings.push(Rect(position = Vector(x, 6.2), anchor = Vector(0, h), w = 1.0, h = h, fill = #232a45))
  for j in 0..math.floor(h / 0.3) {
    for k in 0..3 {
      if (math.sin((i * 7 + j * 3 + k) * 12.9898) * 43758.5453) % 1 > 0.45 {
        windows.push(Vector(x + 0.15 + k * 0.3, 6.05 - j * 0.3))
      }
    }
  }
}
comp.place("buildings", Group(...buildings), in = 0s, out = total)

# 窓は 13 秒から 6 秒の間に、順番とは関係なくばらばらに点く
func lit_windows(t) {
  Group(...windows.enumerate().map(func (pair) {
    let on_at = 13s + (math.sin(pair[0] * 3.7) * 0.5 + 0.5) * 6s
    Rect(position = pair[1], anchor = Vector(0, 0.16), w = 0.14, h = 0.16, fill = #f6d27a, opacity = linear(t, on_at, on_at + 0.4s, 0, 0.9))
  }))
}
comp.place("windows", lit_windows, in = 0s, out = total)

# 人: (足元の高さ, 箱の幅, 手前の色, 奥の色, 出る時刻)。奥から順に置く
let people = [
  (6.9, 2.4, #8d93a8, #5c6278, 0.5s),
  (7.2, 3.0, #9aa1b8, #666d86, 4s),
  (7.6, 3.8, #c2c8dc, #7f8699, 2s),
  (8.2, 4.8, #e2b46a, #9c7a45, 6.5s),
  (8.7, 6.0, #e8ecf7, #8b93a7, 0s),
