# globe.moph — 回る球の上の点を 2D の円で打つ。面は描かず、3D の座標計算だけを使う。
# 奥行きで大きさ・明るさ・重なりの順を決めると、円だけで立体に見える (space3d の例)

import space3d
import color
import math

let len = 12s
let comp = Composition(box = Vector(16, 9), duration = len)
comp.place("bg", Rect(position = Vector(0, 0), anchor = Vector(0, 0), w = 16, h = 9, fill = #0a0e18), in = 0s, out = len)

let cam = space3d.PerspectiveCamera(from = (0, 1.6, 13), to = (0, 0, 0), fov = 0.6, box = (16, 9))
# 点だけ使うので、面の細かさは要らない
let ball = space3d.sphere((0, 0, 0), 3, 11, 22)
# 衛星の軌道。xz 平面に円を作って、傾けた折れ線にする
let round = []
for i in 0..=36 {
  let a = math.tau * i / 36
  round.push((4.2 * math.cos(a), 0, 4.2 * math.sin(a)))
}
let tilt = space3d.Transform3().rotate_z(0.42)
let ring = space3d.path(round).transformed(tilt)

let near = #a8ecff
let far = #1d3b6b

# 球の点・軌道の線・衛星を (奥行き, 図形) の組にして集め、奥から並べて 1 つの Group にする。
# 奥から描けば手前が上に乗る
func spin(t) {
  let turn = space3d.Transform3().rotate_y(t / len * math.tau).rotate_x(0.31)
  let drawn = []

  let moved = turn.apply_all(ball.points)
  # 投影と奥行きはまとめて出す (ループは Rust の中で回る)
  let flat = cam.project_all(moved)
  let deep = cam.depth_all(moved)
  for i in 0..moved.len() {
    # 手前が 1、奥が 0。球の直径ぶんで割る
    let k = (16.1 - deep[i]) / 6
    drawn.push((deep[i], Circle(position = flat[i], radius = 0.03 + 0.05 * k, fill = color.mix(far, near, k))))
  }

  # 軌道の線も同じ奥行きで並べる。折れ線なので、i 番目の線は i と i + 1 の間
  let spun = ring.transformed(turn)
  let rail_deep = cam.depth_all(spun.points)
  for (i, e) in spun.edges(cam).enumerate() {
    drawn.push(((rail_deep[i] + rail_deep[i + 1]) / 2, Line(from = e[0], to = e[1], stroke = #35507a, strokeWidth = 0.03)))
  }

  # 衛星は軌道の上を 3 周する。遠いと小さく見えるので、大きさは scale_at から
  let a = math.tau * (t / len * 3 % 1)
  let here = turn.apply(tilt.apply((4.2 * math.cos(a), 0, 4.2 * math.sin(a))))
  drawn.push((cam.depth(here), Circle(position = cam.project(here), radius = 0.09 * cam.scale_at(here), fill = #ffd98a)))

  Group(...drawn.sort_by(func (d) { -d[0] }).map(func (d) { d[1] }))
}
comp.place("globe", spin, in = 0s, out = len)

output comp

# blocks.moph — 等角のカメラで積み木を並べ、中心から広がる波で上下させる。
# 面の向きと光で陰を付け、面を奥の順に並べて重なりを決める (space3d の例)

import space3d
import math
import color

let len = 10s
let comp = Composition(box = Vector(16, 9), duration = len)
comp.place("bg", Rect(position = Vector(0, 0), anchor = Vector(0, 0), w = 16, h = 9, fill = #0f1420), in = 0s, out = len)

# 等角投影は視点を持たない。unit が 3D の 1 単位ぶんの箱の長さ
let cam = space3d.IsometricCamera(unit = 0.82, box = (16, 9))
let light = (0.55, 1, 0.3)
let base = #6ea8ff

# 床の格子は動かないので 1 度だけ投影する
let floor_lines = space3d.grid((0, 0, 0), 10.5, 10.5, 1.5).edges(cam).map(func (e) {
  Line(from = e[0], to = e[1], stroke = #22304d, strokeWidth = 0.025)
})
comp.place("floor", Group(...floor_lines), in = 0s, out = len)

let side = 5

# 積み木 1 つの見える面 (多くて 3 枚) を (奥行き, 多角形) の組にして返す
func faces_of(x, z, h) {
  space3d.box((x, h / 2, z), (1.05, h, 1.05)).faces(cam).map(func (f) {
    # 高いほど明るい色にしてから、面の向きで陰を付ける
    (f.depth, Polygon(points = f.points, fill = space3d.shade(color.mix(base, #a9e0ff, h / 2.3), f.normal, light), stroke = #0f1420, strokeWidth = 0.02))
  })
}

# 中心から外へ広がる波。高さだけ変えて、毎コマ全部の面を集めて奥から並べる
func wave(t) {
  let drawn = []
  for i in 0..side {
    for j in 0..side {
      let x = (i - (side - 1) / 2) * 1.5
      let z = (j - (side - 1) / 2) * 1.5
      let r = math.sqrt(x * x + z * z)
      let h = 0.4 + 1.9 * (0.5 + 0.5 * math.sin(math.tau * (t / len * 2 - r / 7)))
      for f in faces_of(x, z, h) {
        drawn.push(f)
      }
    }
  }
  # 積み木どうしの重なりは、面の奥行きで決める (遠いほど後ろ)
  Group(...drawn.sort_by(func (f) { -f[0] }).map(func (f) { f[1] }))
}
comp.place("blocks", wave, in = 0s, out = len)

output comp

# helix.moph — 二重らせんを回す。面を 1 枚ずつ図形に開かず、World を図形の fill に入れて
# Mesh のまま GPU に描かせる。1 コマの仕事は Solid の置き方を作ることだけなので、
# 玉をいくら細かくしてもスクリプトの手間は変わらない (space3d の例)

import space3d
import math
import color

let len = 12s
let comp = Composition(box = Vector(16, 9), duration = len)

let cam = space3d.PerspectiveCamera(from = (0, 2.2, 17), to = (0, 0, 0), fov = 0.56, box = (16, 9))

# 形は 1 つずつ作って使い回す。どこに置くかは Solid の transform が持つ
let radius = 2.4
let bead = space3d.sphere((0, 0, 0), 0.45, 12, 24)
let bar = space3d.box((0, 0, 0), (0.16, 0.16, radius * 2))

let steps = 20
let twist = 1 / 9     # 横木 1 つあたり何周ぶん回るか
let pitch = 0.62      # 横木どうしの間隔

# 鎖 2 本を色で分ける。それぞれ端から端へ明るくなる
let chains = [(#2f6fd0, #86d8ff), (#d9552c, #ffb583)]

# 横木は段に 1 つ、玉は 2 本の鎖に 1 つずつ。World に入れる順は問わない (前後は深度で決まる)
func parts_at(t) {
  let parts = []
  for i in 0..steps {
    # 段の置き方。x 軸まわりに回してから、軸に沿って送る
    let place = space3d.Transform3().rotate_x((t / len + i * twist) * math.tau).translate(((i - (steps - 1) / 2) * pitch, 0, 0))
    parts.push(space3d.Solid(mesh = bar, fill = #7d90ad, transform = place))
    let k = i / (steps - 1)
    for s in 0..2 {
      # らせんに沿って波が進む。玉の大きさだけ変える
      let size = 0.88 + 0.18 * math.sin(math.tau * (t / len * 2 - i / steps))
      # 玉は横木の両端。まず自分の場所まで出してから、段ごと回す
      let spot = space3d.Transform3().scale(size).translate((0, 0, if s == 0 { radius } else { -radius })).then(place)
      parts.push(space3d.Solid(mesh = bead, fill = color.mix(chains[s][0], chains[s][1], k), transform = spot))
    }
  }
  parts
}

# World は自分の背景も塗るので、後ろに Rect を敷かなくていい
func helix(t) {
  Rect(position = Vector(0, 0), anchor = Vector(0, 0), w = 16, h = 9,
       fill = space3d.World(camera = cam, parts = parts_at(t), light = (0.35, 0.9, 0.5), ambient = 0.22, background = #0b0f1a))
}
comp.place("helix", helix, in = 0s, out = len)

output comp

